import{z as o,x as p,o as t,c as B,q as s,j as n,D as e,d as i,s as E,S as l,b as r}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"BGP 劫持与 RPKI","description":"","frontmatter":{"title":"BGP 劫持与 RPKI","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bgp-hijack-rpki.md","filePath":"cs/bgp-hijack-rpki.md","lastUpdated":1791063341000}'),d={name:"cs/bgp-hijack-rpki.md"};function R(P,a,c,h,m,C){const A=p("Mermaid");return t(),B("div",null,[a[2]||(a[2]=s('<h1 id="bgp-劫持与-rpki" tabindex="-1">BGP 劫持与 RPKI <a class="header-anchor" href="#bgp-劫持与-rpki" aria-label="Permalink to &quot;BGP 劫持与 RPKI&quot;">​</a></h1><div class="epigraph"><p>任何人都可以通告「更长前缀」或更短 AS_PATH；RPKI 用证书绑定前缀与源 AS，ROV 把不匹配当无效，仍不证明整条路径。</p><footer>—— 据 RFC 6480 RPKI；RFC 6811 源验证；RFC 4271 对照整理</footer></div><p><a href="/cs/bgp-convergence-dampening">上一课</a> 假定通告是真的。缺口是<strong>假通告</strong>：劫持、泄露、更长前缀抢 LPM。RPKI/ROA 验<strong>源 AS</strong>，不是验 AS_PATH 全程。本课不把 IXP 交换结构写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>决策过程相信属性。攻击者向提供者通告你的 /24，全球 LPM 把流量拐走。YouTube/Pakistan 2008 一类事件是操作错误也是协议无认证。RPKI：地址局发证书，前缀持有者签 ROA（前缀、最大长度、源 AS）。路由器 ROV：未知/无效/有效三态，政策决定是否丢无效。路径上的中间 AS 仍可撒谎——BGPsec 部署稀少，本课点名不展开。</p><p><span class="marginnote">数字实例：目的地址 203.0.113.66 同时撞上 203.0.113.0/24（合法）与 203.0.113.64/25（劫持者通告），后者前缀更长、按 LPM 胜出，流量被拐走——/25 哪怕无人授权，只要没人过滤就能全球扩散。</span></p><p>不要把 RPKI 写成 DNSSEC：对象都是证书树，验证的名字空间不同。</p><p><span class="marginnote">RFC 6480、6811。IRR 过滤是弱对照。本课不给攻击步骤，只给防御对象。</span></p><h3 id="rov-只验源" tabindex="-1">ROV 只验源 <a class="header-anchor" href="#rov-只验源" aria-label="Permalink to &quot;ROV 只验源&quot;">​</a></h3><p>更长前缀仍吃 LPM。ROA 不证明 AS_PATH 全程。泄露是政策错误，不是源伪造。无效当未知则保护为空。</p><p><span class="marginnote">术语翻译：ROA 是前缀持有者签发的「授权书」，写明哪个 AS 有权广播这段地址、最长可拆到多细；ROV 则是路由器拿着授权书核对来路，对不上就判「无效」，可按政策拒收。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：ROA 发布 → 验证缓存 → 路由器政策。对照前缀列表手工过滤：ROA 随证书更新。更长前缀：ROA maxLength 要覆盖，否则自己的拆分变无效。</p>',13)),(t(),n(l,null,{default:e(()=>[E(A,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20CER%5B%22%E8%AF%81%E4%B9%A6%E6%A0%91%22%5D%20--%3E%20ROA%5B%22ROA%3A%20%E5%89%8D%E7%BC%80%E4%B8%8E%E6%BA%90%20AS%22%5D%0A%20%20ROA%20--%3E%20ROV%5B%22%E8%B7%AF%E7%94%B1%E5%99%A8%E6%BA%90%E9%AA%8C%E8%AF%81%22%5D%0A%20%20ROV%20--%3E%20POL%5B%22%E4%B8%A2%E6%97%A0%E6%95%88%E6%88%96%E9%99%8D%E6%9D%83%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[i("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"收敛与劫持叠加：错误通告也会被探索、被 dampen。IRR 与 RPKI 可同时用。主干安全 CIA：这里主要是完整性与可用性（流量被拐、前缀被压）。机密性不在 BGP。",-1)),a[5]||(a[5]=r("p",null,"同一目的地址，多条通告在路由器里怎么比：",-1)),(t(),n(l,null,{default:e(()=>[E(A,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E5%90%88%E6%B3%95%20AS%20100%EF%BC%9A203.0.113.0%2F24%22%5D%20--%3E%20R%5B%22%E8%B7%AF%E7%94%B1%E5%99%A8%E9%80%89%E8%B7%AF%EF%BC%88LPM%EF%BC%89%22%5D%0A%20%20H1%5B%22%E5%8A%AB%E6%8C%81%20AS%20666%EF%BC%9A%E5%90%8C%E4%B8%80%20%2F24%22%5D%20--%3E%20R%0A%20%20H2%5B%22%E5%8A%AB%E6%8C%81%20AS%20666%EF%BC%9A%E6%9B%B4%E9%95%BF%20%2F25%22%5D%20--%3E%20R%0A%20%20R%20--%3E%7C%22%E6%9B%B4%E9%95%BF%E5%89%8D%E7%BC%80%E4%BC%98%E5%85%88%22%7C%20W%5B%22%E6%B5%81%E9%87%8F%E6%8B%90%E5%90%91%20%2F25%20%E5%8A%AB%E6%8C%81%E8%80%85%22%5D%0A%20%20R%20--%3E%7C%22%E7%AD%89%E9%95%BF%E7%AB%9E%E4%BA%89%22%7C%20T%5B%22%E6%AF%94%20AS_PATH%20%E4%B8%8E%E6%9C%AC%E5%9C%B0%E6%94%BF%E7%AD%96%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">常见误区：以为开了 RPKI 就万事大吉。ROV 只核对「源 AS」这一环；中间 AS 伪造路径、或合法机构把前缀从错误出口泄出去，授权书都拦不住——后者是政策错误，不是源伪造，要靠过滤与监控补。</span></p><p>泄露：合法源、错误出口政策，ROA 验不过泄露路径；需要政策与监控。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 BGPsec 的逐跳签名部署。互联网拓扑与 IXP 是下一课。后课默认：RPKI 护源，不护路径；LPM 仍使更长前缀危险。</p><p>关闭 ROV 或把无效当未知，保护为空。</p><p>下一课<a href="/cs/internet-ixp">互联网拓扑与 IXP</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>劫持利用信任与 LPM，不是破密码。</li><li>ROA+ROV 验证源 AS 与最大长度。</li><li>不证明 AS_PATH 真实。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 6480；RFC 6811。</li></ul>',8))])}const u=o(d,[["render",R]]);export{_ as __pageData,u as default};
